        public override void ToggleFeature() => CozyPreferences.CurrentStyle.ToggleSkyMoonDisk();

        /// <summary>
        /// Sets the color of the moon sprite in the sky.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the color of the moon sprite in the sky.")]
        [BlockProperty(VarType.Color, "Color")]
        public BlockColorValue color = new BlockColorValue(default);
        /// <summary>
        /// Sets the size of the moon sprite in the sky.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the size of the moon sprite in the sky.")]
        [BlockProperty(VarType.Float, "Size")]
        public BlockFloatValue size = new BlockFloatValue(default);
        /// <summary>
        /// Changes the orientation of the moon sprite in the sky.
        /// </summary>
        [CozySearchable]
        [Tooltip("Changes the orientation of the moon sprite in the sky.")]
        [BlockProperty(VarType.Float, "Rotation", minFloat = 0, maxFloat = 1)]
        public BlockFloatValue rotation = new BlockFloatValue(default);
        /// <summary>
        /// Sets the strength of the normal map for the moon.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the strength of the normal map for the moon.")]
        [BlockProperty(VarType.Float, "NormalStrength")]
        public BlockFloatValue normalStrength = new BlockFloatValue(default);
        /// <summary>
        /// Sets the strength of the declination. Declination offsets the moon from the celestial plane (in line with the sun). Moves back and forth following a sine wave.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the strength of the declination. Declination offsets the moon from the celestial plane (in line with the sun). Moves back and forth following a sine wave.")]
        [BlockProperty(VarType.Float, "Declination")]
        public BlockFloatValue declination = new BlockFloatValue(default);
        /// <summary>
        /// Set the number of days between full cycles of declination.
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the number of days between full cycles of declination.")]
        [BlockProperty(VarType.Float, "DeclinationPeriod")]
        public BlockFloatValue declinationPeriod = new BlockFloatValue(default);
        /// <summary>
        /// Offsets the period for the sine wave of declination.
        /// </summary>
        [CozySearchable]
        [Tooltip("Offsets the period for the sine wave of declination.")]
        [BlockProperty(VarType.Float, "DeclinationOffset")]
        public BlockFloatValue declinationOffset = new BlockFloatValue(default);
        /// <summary>
        /// Set the number of days between full cycles the orbit.
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the number of days between full cycles the orbit.")]
        [BlockProperty(VarType.Float, "OrbitPeriod")]
        public BlockFloatValue orbitPeriod = new BlockFloatValue(default);
        /// <summary>
        /// Offsets the period for the orbit.
        /// </summary>
        [CozySearchable]
        [Tooltip("Offsets the period for the orbit.")]
        [BlockProperty(VarType.Float, "OrbitOffset")]
        public BlockFloatValue orbitOffset = new BlockFloatValue(default);

        public override bool CaptureFromParameters(AtmosphereParameters parameters) {
            color = new BlockColorValue(parameters.skyMoonDiskColor);
            size = new BlockFloatValue(parameters.skyMoonDiskSize);
            rotation = new BlockFloatValue(parameters.skyMoonDiskRotation);
            normalStrength = new BlockFloatValue(parameters.skyMoonDiskNormalStrength);
            declination = new BlockFloatValue(parameters.skyMoonDiskDeclination);
            declinationPeriod = new BlockFloatValue(parameters.skyMoonDiskDeclinationPeriod);
            declinationOffset = new BlockFloatValue(parameters.skyMoonDiskDeclinationOffset);
            orbitPeriod = new BlockFloatValue(parameters.skyMoonDiskOrbitPeriod);
            orbitOffset = new BlockFloatValue(parameters.skyMoonDiskOrbitOffset);
            return true;
        }

        public override void ApplyToWeatherSphere(AtmosphereParameters parameters, float weight) {
            if (!active || !FeatureEnabledGlobally) return;
            if (!color.disabled)
                parameters.skyMoonDiskColor.Lerp(color.value, weight);
            if (!size.disabled)
                parameters.skyMoonDiskSize.Lerp(size.value, weight);
            if (!rotation.disabled)
                parameters.skyMoonDiskRotation.Lerp(rotation.value, weight);
            if (!normalStrength.disabled)
                parameters.skyMoonDiskNormalStrength.Lerp(normalStrength.value, weight);
            if (!declination.disabled)
                parameters.skyMoonDiskDeclination.Lerp(declination.value, weight);
            if (!declinationPeriod.disabled)
                parameters.skyMoonDiskDeclinationPeriod.Lerp(declinationPeriod.value, weight);
            if (!declinationOffset.disabled)
                parameters.skyMoonDiskDeclinationOffset.Lerp(declinationOffset.value, weight);
            if (!orbitPeriod.disabled)
                parameters.skyMoonDiskOrbitPeriod.Lerp(orbitPeriod.value, weight);
            if (!orbitOffset.disabled)
                parameters.skyMoonDiskOrbitOffset.Lerp(orbitOffset.value, weight);
        }
    }


}